@export
def operations():
    d = {'a': 1, 'b': 2}
    alias = d
    copy = dict(d)
    d['c'] = 3
    d['a'] = 10
    alias['d'] = 4
    out = [d['a'], 'c' in d, 'z' in d, 'b' in d.keys(), 'z' not in d.keys()]
    out.append(d.get('b'))
    out.append(d.get('z', -1))
    out.append(d.pop('b'))
    out.append(d.pop('z', -2))
    out.append(d.popitem())
    out.append(d.setdefault('a', 0))
    out.append(d.setdefault('e', 5))
    d.update({'f': 6, 'a': 11})
    d.update([('g', 7)], h=8)
    out.append(list(d.items()))
    out.append(list(copy.items()))
    out.append(alias is d)
    literal = {**d, 'a': 12, 'i': 9}
    comprehension = {k: v * 2 for k, v in d.items() if v > 5}
    pairs = dict([('x', 1), ('x', 2)], y=3)
    keys = dict.fromkeys(['p', 'q', 'p'], 0)
    union = d | {'a': 13, 'j': 10}
    d |= {'k': 11}
    out.append([list(literal.items()), list(comprehension.items()), list(pairs.items())])
    out.append([list(keys.items()), list(union.items()), list(d.items())])
    mixed = {1: 'int', True: 'bool', (1, 2): 'tuple', frozenset([1, 2]): 'set'}
    out.append([mixed[1], mixed[True], mixed[(1, 2)], mixed[frozenset([2, 1])], len(mixed)])
    return out

@export
def scale(n: int):
    d = {}
    for i in range(n):
        d['k' + str(i)] = i
    total = 0
    for i in range(n):
        total += d['k' + str(i)]
    for i in range(n):
        d.pop('k' + str(n - 1 - i))
    return [total, len(d)]

@export
def errors(kind: str):
    d = {'a': 1}
    if kind == 'missing':
        return d['z']
    if kind == 'unhashable':
        d[[1]] = 1
    if kind == 'pop':
        return d.pop('z')
    if kind == 'popitem':
        d.popitem()
        return d.popitem()
